INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG12_SEC_004', 'Secondary education', 'Sustainability mindset', 'Participation in eco-school programmes, climate strikes and sustainability campaigns.', 'Active'), ('CFV_SDG12_SEC_005', 'Secondary education', 'Advocacy and leadership', 'Engage in peer-led campaigns or debates on environmental issues.', 'Active'), ('CFV_SDG12_SEC_006', 'Secondary education', 'Advocacy and leadership', 'Propose innovative solutions for reducing waste or improving consumption behaviours in their school or community.', 'Active'), ('CFV_SDG12_SEC_007', 'Secondary education', 'Reflection and empowerment', 'Engage in reflective practices that examine their own lifestyles and purchasing behaviours.', 'Active'), ('CFV_SDG12_SEC_008', 'Secondary education', 'Reflection and empowerment', 'Commitment to lifelong sustainable habits and to question the ethical dimensions of consumption.', 'Active'), ('CFV_SDG12_TVET_001', 'TVET', 'Environmental responsibility', 'Promote accountability and ethics in technical professions regarding environmental and social impacts.', 'Active'), ('CFV_SDG12_TVET_002', 'TVET', 'Environmental responsibility', 'Cultivate an appreciation of the finite nature of resources and the need for long-term thinking in production roles.', 'Active'), ('CFV_SDG12_TVET_003', 'TVET', 'Empowered professional identity', 'See themselves as agents of change in their industries – able to advocate for and implement sustainable practices.', 'Active'), ('CFV_SDG12_TVET_004', 'TVET', 'Empowered professional identity', 'Cultivate pride in contributing to sustainable development and circular economies.', 'Active'), ('CFV_SDG12_TVET_005', 'TVET', 'Commitment to systemic change', 'Proactive mindset to challenge unsustainable norms and push for greener standards and policies.', 'Active'), ('CFV_SDG12_TVET_006', 'TVET', 'Commitment to systemic change', 'Encourage collaborative problem solving for local and global sustainability challenges in teams, businesses and communities.', 'Active'), ('CFV_SDG12_TVET_007', 'TVET', 'Equity and inclusion', 'Promote inclusive production and consumption models that support decent work, ethical sourcing and the wellbeing of vulnerable populations.', 'Active'), ('CFV_SDG12_TVET_008', 'TVET', 'Equity and inclusion', 'Integrate gender-sensitive and community-led approaches in consumption/production strategies.', 'Active'), ('CFV_SDG12_TER_001', 'Tertiary education', 'Ethical leadership and accountability', 'Develop a strong sense of accountability and integrity in leadership roles – balancing environmental, economic and social responsibilities.', 'Active'), ('CFV_SDG12_TER_002', 'Tertiary education', 'Ethical leadership and accountability', 'Champion green business practices, public policy reforms and corporate transparency.', 'Active'), ('CFV_SDG12_TER_003', 'Tertiary education', 'Systemic thinking and global citizenship', 'Recognise the interconnectedness of environment, economy and society, and the need for integrated approaches.', 'Active'), ('CFV_SDG12_TER_004', 'Tertiary education', 'Systemic thinking and global citizenship', 'Adopt a global perspective on equity and justice in production and consumption, particularly regarding North–South dynamics and access to resources.', 'Active'), ('CFV_SDG12_TER_005', 'Tertiary education', 'Sustainability as core professional identity', 'Embrace the identity of a change agent committed to advancing sustainability through expertise, teaching, policy or entrepreneurship.', 'Active'), ('CFV_SDG12_TER_006', 'Tertiary education', 'Sustainability as core professional identity', 'Drive sustainable innovation in sectors such as agriculture, energy, finance, construction and design.', 'Active'), ('CFV_SDG12_TER_007', 'Tertiary education', 'Commitment to equity and participation', 'Value inclusive processes that consider local knowledge, gender equity and marginalised voices in shaping sustainable solutions.', 'Active'), ('CFV_SDG12_TER_008', 'Tertiary education', 'Commitment to equity and participation', 'Promote participatory governance, youth engagement and co-creation in sustainability transitions.', 'Active'), ('CFV_SDG12_ADULT_001', 'Adult education', 'Environmental respect and care', 'Encourage a deep appreciation for the intrinsic value of nature and the role of local ecosystems in community wellbeing.', 'Active'), ('CFV_SDG12_ADULT_002', 'Adult education', 'Environmental respect and care', 'Encourage conservation-minded behaviours, such as using local resources wisely and reducing waste.', 'Active'), ('CFV_SDG12_ADULT_003', 'Adult education', 'Social responsibility and empowerment', 'Cultivate a sense of responsibility for current and future generations in making choices that reduce harm and build resilience.', 'Active'), ('CFV_SDG12_ADULT_004', 'Adult education', 'Social responsibility and empowerment', 'Promote shared ownership of community resources and encourage collective stewardship of public goods.', 'Active'), ('CFV_SDG12_ADULT_005', 'Adult education', 'Commitment to action and equity', 'Value equitable access to sustainable goods and services, and advocate for inclusive community-based solutions.', 'Active'), ('CFV_SDG12_ADULT_006', 'Adult education', 'Commitment to action and equity', 'Build confidence to act – individually and collectively – for more sustainable, just and resilient communities.', 'Active'), ('CFV_SDG12_ADULT_007', 'Adult education', 'Lifelong learning for sustainability', 'Embrace lifelong learning as essential for adapting to change and building sustainable futures.', 'Active'), ('CFV_SDG12_ADULT_008', 'Adult education', 'Lifelong learning for sustainability', 'Promote a mindset of curiosity, adaptability and continual improvement in sustainable living and livelihoods.', 'Active'), ('CFV_SDG13_SEC_001', 'Secondary education', 'Critical thinking and awareness', 'Analyse climate issues thoughtfully, considering multiple perspectives and solutions.', 'Active'), ('CFV_SDG13_SEC_002', 'Secondary education', 'Critical thinking and awareness', 'Evaluate behaviours and lifestyle choices to reduce CO₂ emissions, conserve energy, and promote sustainable consumption.', 'Active'), ('CFV_SDG13_SEC_003', 'Secondary education', 'Commitment to climate justice', 'Recognise inequalities in climate impacts and advocate for fair and equitable solutions.', 'Active'), ('CFV_SDG13_SEC_004', 'Secondary education', 'Commitment to climate justice', 'Engage actively in climate action initiatives that contribute to Sustainable Development Goals locally and globally.', 'Active'), ('CFV_SDG13_SEC_005', 'Secondary education', 'Individual and collective action', 'Participate in community climate education, sharing knowledge and promoting dialogue.', 'Active'), ('CFV_SDG13_SEC_006', 'Secondary education', 'Individual and collective action', 'Contribute to collective initiatives that strengthen local and regional resilience.', 'Active'), ('CFV_SDG13_SEC_007', 'Secondary education', 'Global responsibility and systems thinking', 'Understand the interconnectedness of social, economic, and environmental systems.', 'Active'), ('CFV_SDG13_SEC_008', 'Secondary education', 'Global responsibility and systems thinking', 'Act as responsible citizens aware of the broader implications of local actions on global climate outcomes.', 'Active'), ('CFV_SDG13_SEC_009', 'Secondary education', 'Problem-solving and innovation', 'Identify climate challenges and propose practical, actionable solutions.', 'Active'), ('CFV_SDG13_SEC_010', 'Secondary education', 'Problem-solving and innovation', 'Apply creative thinking to design context-appropriate mitigation and adaptation strategies.', 'Active'), ('CFV_SDG13_SEC_011', 'Secondary education', 'Resilience and adaptability', 'Develop the capacity to respond proactively to changing environments and uncertain futures.', 'Active'), ('CFV_SDG13_SEC_012', 'Secondary education', 'Resilience and adaptability', 'Build flexibility and perseverance in the face of climate-related challenges.', 'Active'), ('CFV_SDG13_SEC_013', 'Secondary education', 'Applied learning', 'Evaluate local and global evaluation of climate policies, projects, and grassroots initiatives.', 'Active'), ('CFV_SDG13_SEC_014', 'Secondary education', 'Applied learning', 'Community awareness campaigns, sustainable school projects, and climate action planning.', 'Active'), ('CFV_SDG13_SEC_015', 'Secondary education', 'Applied learning', 'Integrate climate considerations into economics, geography, science, and social studies.', 'Active'), ('CFV_SDG13_TVET_001', 'TVET', 'Sustainability and professional responsibility', 'Apply low-carbon, climate-resilient practices within the learner’s industry.', 'Active'), ('CFV_SDG13_TVET_002', 'TVET', 'Sustainability and professional responsibility', 'Take responsibility for reducing environmental impacts through everyday professional actions.', 'Active'), ('CFV_SDG13_TVET_003', 'TVET', 'Ethical and evidence-based decision-making', 'Integrate climate ethics into workplace decisions.', 'Active'), ('CFV_SDG13_TVET_004', 'TVET', 'Ethical and evidence-based decision-making', 'Ensure fairness, accountability, and responsible resource management in professional contexts.', 'Active'), ('CFV_SDG13_TVET_005', 'TVET', 'Innovation and problem-solving', 'Develop practical and creative solutions to environmental challenges.', 'Active'), ('CFV_SDG13_TVET_006', 'TVET', 'Innovation and problem-solving', 'Pursue entrepreneurial opportunities that combine sustainability with economic viability.', 'Active') ON CONFLICT DO NOTHING;